class EmssimProcessStarter(EMSSInterface):
    """
    EMSsim keywords to start/stop/restart EMSsim session
    """

    def __init__(self):
        super(EmssimProcessStarter, self).__init__()

        self._time_tcp_connected = None
        self._time_enb_discovered = None

        default_log_dir = os.getenv('EMSSIM_LOG_DIR', self.log_dir)
        if os.path.isdir(default_log_dir):
            os.environ['RUFF_LOGDIR'] = default_log_dir

    def setup_emss(self, timeout=240, bts_timeout=600, which_emss=None, wait_tcp_connected=False, wait_connected=True, wait_discovered=True,
                   enb_id=None, bts_id=None, alias=None, host=None, port=None, server_port=None, user=None, logging=True, debug_fbox=False,
                   reg_user=None, reg_password=None, tls=False, pnp=False, ac=False, certm=False, ne3s=True, run_apps=True,
                   manager_id=None, oam_ip=None, bts_ip=None, **start_params):
        """
        Setups library and starts (if ute cloud) EMSsim session.

        :param timeout: int - maximum time in seconds to wait for emssim session to start (default=240).
        :param bts_timeout: int - maximum time in seconds to wait for bts connection and discovery (default=360).
        :param which_emss: Obsolete, use bts_id instead.
        :param wait_tcp_connected: wait only for bts TCP connection (default=False).
            If wait_tcp_connected is True then do not wait for OAM connection and discovery.
        :param wait_connected: wait for bts OAM connection (default=True).
            If wait_connected is False then do not wait for discovery.
        :param wait_discovered: wait for bts discovery (default=True).
            If wait_discovered is True then waits for bts connection first.
        :param bts_id (enb_id): int - EMSsim instance number to be started.
            The instance number corresponds to BTS user name for which EMSsim should be started,
            e.g. bts_id=2 will start EMSsim for flexi2.
        :param alias: User defined instance reference used in other keywords to select the correct ta_emss instance
        :param host: EMSsim server IP address (default: taken from ta_emss library constructor)
        :param port: EMSsim session JSON TCP port (default: 4000 + bts_id)
        :param server_port: EMSsim session USER TCP port (default: port + 3000)
        :param user: EMSsim session user (overwrites default flexi<bts_id> user)
        :param logging: Start fbox and EMsim session logging (default=True)
        :param debug_fbox: If logging is True then start fbox log with debugs (default=False)
        :param reg_user: Registration user for NE3S activation
        :param reg_password: Registration password for NE3S activation
        :param tls: enable TLS on OAM link (default=False)
        :param pnp: activate PlugAndPlay functionality (default=False)
        :param ac: activate PlugAndPlay with Auto Configuration manager only (default=False)
        :param certm: use soc_certm.xml for common manager instead of default soc.xml (default=False)
        :param ne3s: Use Netact NE3S and activate COAM (default=True). If variable OM_TYPE=BTSMED then activate SOAM instead.
        :param run_apps: Start fbox and emssim session if not started yet (default=True).
        :param manager_id: Use custom manager_id for NE3S registration.
        :param oam_ip: Additional OAM IP to be added to the existing Primary OAM IP already specified as data_server in /etc/emssim.conf
        :param bts_ip: Together with provided 'user' option will add the new BTS user with given BTS IP
        :param start_params: a set of parameters passed to emssim session start script.

        +----------------+-------------------+
        |  Examples                          |
        +================+===================+
        |  setup_emss    | bts_id=2          |
        +----------------+-------------------+
        """
        timeout = self._opt_int(timeout)
        bts_timeout = self._opt_int(bts_timeout)
        which_emss = self._opt_int(which_emss)
        wait_tcp_connected = self._opt_bool(wait_tcp_connected)
        wait_connected = self._opt_bool(wait_connected)
        wait_discovered = self._opt_bool(wait_discovered)
        bts_id = self._opt_id(enb_id, bts_id)
        port = self._opt_int(port)
        server_port = self._opt_int(server_port)
        logging = self._opt_bool(logging)
        debug_fbox = self._opt_bool(debug_fbox)
        tls = self._opt_bool(tls)
        pnp = self._opt_bool(pnp)
        ac = self._opt_bool(ac)
        certm = self._opt_bool(certm)
        ne3s = self._opt_bool(ne3s)
        run_apps = self._opt_bool(run_apps)

        setup_args = {
            'timeout': timeout,
            'bts_timeout': bts_timeout,
            'which_emss': which_emss,
            'wait_tcp_connected': wait_tcp_connected,
            'wait_connected': wait_connected,
            'wait_discovered': wait_discovered,
            'enb_id': enb_id,
            'bts_id': bts_id,
            'alias': alias,
            'host': host,
            'port': port,
            'server_port': server_port,
            'user': user,
            'logging': logging,
            'debug_fbox': debug_fbox,
            'reg_user': reg_user,
            'reg_password': reg_password,
            'tls': tls,
            'pnp': pnp,
            'ac': ac,
            'certm': certm,
            'ne3s': ne3s,
            'run_apps': run_apps,
            'manager_id': manager_id,
            'oam_ip': oam_ip,
            'bts_ip': bts_ip,
            'start_params': start_params,
        }

        inst_id = None

        if which_emss:
            inst_id = which_emss

        if bts_id:
            inst_id = bts_id

        self._print("setup_emss: host=%s, port=%s, inst_id=%s, last_bts_id=%s, alias=%s, user=%s" % (host, port, inst_id, self.last_bts_id, alias, user))
        self._print("setup_emss: wait: tcp_connected=%s, connected=%s, discovered=%s" % (wait_tcp_connected, wait_connected, wait_discovered))

        if host is None and port is None and inst_id is None and alias is None:
            self._print("setup_emss: No address information")
            return

        self._verify_add_user(user=user, bts_ip=bts_ip, force=True)

        if port is None and user is not None:
            port = self._get_port_from_start_script(user=user)

        if server_port is None and user is not None:
            server_port = self._get_server_port_from_start_script(user=user)

        self = self._get_instance(inst_id, alias=alias, host=host, port=port, check_emss=False, server_port=server_port, user=user,
                                  timeout=timeout, bts_timeout=bts_timeout, which_emss=which_emss, wait_tcp_connected=wait_tcp_connected,
                                  wait_connected=wait_connected, wait_discovered=wait_discovered, logging=logging,
                                  debug_fbox=debug_fbox, reg_user=reg_user, reg_password=reg_password, tls=tls, pnp=pnp, ac=ac,
                                  certm=certm, ne3s=ne3s, run_apps=run_apps, manager_id=manager_id, oam_ip=oam_ip, bts_ip=bts_ip,
                                  **start_params)

        if inst_id is None:
            inst_id = int(self.instance_id)
            self._print("setup_emss: Got EMSS instance ID=%s" % inst_id)

        self.setup_args = setup_args
        self._which_emss = inst_id
        self._timeout = timeout
        self._bts_timeout = bts_timeout
        self._desired_tcp_connected = wait_tcp_connected
        self._desired_connected = wait_connected
        self._desired_discovered = wait_discovered
        self.logging = logging
        self.reg_user = reg_user
        self.reg_password = reg_password
        self.tls = tls
        self.pnp = pnp
        self.ac = ac
        self.certm = certm
        self.ne3s = ne3s
        self.run_apps = run_apps
        self.manager_id = manager_id
        self.oam_ip = oam_ip
        self.bts_ip = bts_ip
        self.start_params = start_params
        self._time_setup_start = time.time()
        self._time_tcp_connected = None
        self._time_enb_discovered = None
        self._debug_fbox = debug_fbox

        self._run_setup_tasks()

    def _run_setup_tasks(self):
        self._print_info()
        if self.is_ute:
            self._print("## Cleaning old logs")
            self._cleanup_old_logs()

        if self.oam_ip is not None:
            self._print("## Adding secondary oam ip: %s" % self.oam_ip)
            self._add_secondary_oam_ip(self.oam_ip)

        if self.run_apps:
            self._print("## Running apps")
            self._start_apache()
            self._start_fbox_dual()

        self._set_desired_states()

        if self.run_apps and self._is_host_local():
            self._print("## Starting emss session")
            self._start_emss()
            if not self._is_emss_running():
                return

        self._print("## Creating EMSsim device")
        self._create_emssim()
        if self.logging or self.log_om:
            self._print("## Starting LOG system")
            self._log_om_start()
            self._start_loggers(self.robot_log_dir)

        self._print("## Veryfing BTS connectivity and state")
        self._check_if_enb_connected_discovered()
        if self._desired_discovered:
            self._report_adapt()
            self._print("## Creating OM")
            if not self._create_om():
                return
            self._start_loggers(self.robot_log_dir)
        self._report_durations()

    def _get_emssim_env(self):
        # {"BTS":
        #   {"ADAPT_VERSION":{},"ADAPT_VERSION_BTS":{},"ALARM_DIR":"/flexi1/UPLOADS",
        #     "BTSOM_TLS":"Unknown","BTS_NAME":"flexi1","CONF_DIR":"/flexi1/UPLOADS",
        #     "IP_ADDRESS":"10.0.1.2","LOG_ALARM_DIR":"/home/flexi1/ALARM_SUMMARY",
        #     "NE_ID":"1","PDDB_VERSION":"Unknown","STATS_DIR":"/flexi1/UPLOADS"},
        # "CMD":
        #   {"-APACHE_LOADS_DIR":"/home/emssim/LOADS","-APACHE_ROOT_DIR":"/home",
        #     "-BASE_DIR":"/opt/emssim","-BOOST_SHELL":"sim","-BTS_FILE":"bts-file",
        #     "-EMSSIM_VERSION":"4.48.0","-JSON_PORT":"4001","-SCRIPTS_DIR":"/opt/emssim/sim/scripts",
        #     "-SCRIPT_NAME":"flexi","-SDL_DIR":"/var/www/DATA/ENB","-SERVER_PORT":"7001","start":"start_emss"},
        # "LOG":{"DETAIL_LEVEL":"3","LOGFILE":"'/var/log/emssim/emssim.flexi1.20240314_080827.log'","LOG_DIR":""},
        # "PATH":{"BOOST_BASE":"/opt/emssim","OBJECTS_DIR":"/home/objects","SCRIPTS_DIR":"/opt/emssim/sim/scripts","USER_PATH":"None defined\n"},
        # "SCR":{"BOOST_DETAIL":"3","SCREEN_WIDTH":"3000"},
        # "VER":{"CORE_RELEASE":"4.48.0"}}
        ret = {}
        try:
            cmd_env = self.emssim.cmd_env()
            cmd_env.run()
            cmd_env_ret = cmd_env.returned_data()
            ret = cmd_env_ret['env']
        except Exception as exc:
            self._print("Cannot get emssim env: {}".format(exc))
        return ret

    def _check_report_no_adapt_version(self, emssim_env):
        try:
            adapt_bts = emssim_env['BTS']['ADAPT_VERSION_BTS']
            adapt_pddb = emssim_env['BTS']['ADAPT_VERSION']
            adapt_mismatch = ""
            for adapt in sorted(adapt_bts.keys()):
                if adapt in adapt_pddb:
                    if adapt_bts[adapt] != adapt_pddb[adapt]:
                        adapt_mismatch += f"bts({adapt_bts[adapt]}),pddb({adapt_pddb[adapt]}) "
                else:
                    adapt_mismatch += f"bts({adapt_bts[adapt]}),pddb(missing) "
            if adapt_mismatch:
                build_id = emssim_env['BTS']['BUILD_ID'] if 'BUILD_ID' in emssim_env['BTS'] else "Unknown"
                adapt_mismatch = f"{build_id}: " + adapt_mismatch
                self._print("Reporting no_adapt_version: {}".format(adapt_mismatch))
                telemetry.tl_update("no_adapt_version", 1, {"mismatch": adapt_mismatch})
        except Exception as exc:
            self._print("Cannot report no_adapt_version: {}".format(exc))

    def _check_report_no_adapt_file(self, emssim_env):
        try:
            build_id = emssim_env['BTS']['BUILD_ID'] if 'BUILD_ID' in emssim_env['BTS'] else "Unknown"
            pddb_version = emssim_env['BTS']['PDDB_VERSION'] if 'PDDB_VERSION' in emssim_env['BTS'] else "Unknown"
            if pddb_version == "Unknown":
                self._print("Reporting no_adapt_file: {}".format(build_id))
                telemetry.tl_update("no_adapt_file", 1, {"bts_sw_version": build_id})
        except Exception as exc:
            self._print("Cannot report no_adapt_version: {}".format(exc))

    def _check_report_wrong_bts_sw_version(self, emssim_env):
        try:
            build_id = emssim_env['BTS']['BUILD_ID'] if 'BUILD_ID' in emssim_env['BTS'] else "Unknown"
            pddb_version = emssim_env['BTS']['PDDB_VERSION'] if 'PDDB_VERSION' in emssim_env['BTS'] else "Unknown"
            if build_id == "Unknown":
                self._print("Reporting no_bts_sw_version: {}".format(pddb_version))
                telemetry.tl_update("no_bts_sw_version", 1, {"pddb_file": pddb_version})
                return

            build_patterns = [
                r"^ASI\d+R\d+_",
                r"^SBTS\d+R\d+_",
                r"^vCUCNF\d+R\d+_",
                r"^vDUCNF\d+R\d+_",
            ]
            build_ok = False
            for build_pattern in build_patterns:
                srch = re.search(build_pattern, build_id)
                if srch:
                    build_ok = True
                    break
            if not build_ok:
                self._print("Reporting bad_bts_sw_version: {}".format(build_id))
                telemetry.tl_update("bad_bts_sw_version", 1, {"bts_sw_version": build_id})
        except Exception as exc:
            self._print("Cannot report wrong_bts_sw_version: {}".format(exc))

    def _report_adapt(self):
        if self._is_dry_run():
            return

        try:
            if not telemetry.tl_register(self.user):
                return
            emssim_env = self._get_emssim_env()
            build_id = emssim_env['BTS']['BUILD_ID'] if 'BUILD_ID' in emssim_env['BTS'] else "Unknown"
            adapt_bts = emssim_env['BTS']['ADAPT_VERSION_BTS']
            adapt_str = f"{build_id}: "
            for adapt in sorted(adapt_bts.keys()):
                adapt_ver = adapt_bts[adapt]
                adapt_str += f"{adapt}={adapt_ver} "

            self._print("Reporting adapts: {}".format(adapt_str))
            telemetry.tl_trace("adapts", {"adapt_version_bts": adapt_str})

            self._check_report_wrong_bts_sw_version(emssim_env)
            self._check_report_no_adapt_version(emssim_env)
            self._check_report_no_adapt_file(emssim_env)

        except Exception as exc:
            self._print("Cannot report adapt: {}".format(exc))

