    def teardown_emss(self, enb_id=None, bts_id=None, alias=None):
        """
        Stops EMSsim session.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------+-------------------+
        |  Examples                          |
        +================+===================+
        |  teardown_emss | bts_id=2          |
        +----------------+-------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias, check_emss=False)

        self._stop_emss(check_if_host_local=True)

    def recover_all_emss_connections(self):
        """
        Recovers EMSsim session.

        +---------------------------------+
        |  Examples                       |
        +=================================+
        |  recover_all_emss_connections   |
        +---------------------------------+
        """

        instance_ids = self.get_enb_ids_with_created_emss_instances(discovered=False)
        for inst_id in instance_ids:
            rec_start = time.time()
            self.recover_emss_connection(enb_id=inst_id)
            rec_stop = time.time()
            self = self._get_instance(inst_id, check_emss=False)
            print('Recovered emmsim for eNB :{} after: {}s'.format(self.om.get_enb_id(), int(rec_stop - rec_start)))

    def recover_emss_connection(self, enb_id=None, bts_id=None, alias=None):
        """
        Restarts EMSsim session.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +--------------------------+-----------------+
        |  Examples                                  |
        +==========================+=================+
        |  recover_emss_connection | bts_id=2        |
        +--------------------------+-----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias, check_emss=False)

        self.check_emss = False
        self.teardown_emss(bts_id=self.instance_id, alias=self.alias)
        self._run_setup_emss()
        self.check_emss = True
        self._assert(self.emssim, "Cannot connect to EMSsim")
        self._assert(self.emssim.check_hb(), "Cannot recover EMSsim connection")

    def start_emss(self, timeout=180, enb_id=None, bts_id=None, alias=None, host=None, port=None, **start_params):
        """
        Starts EMSsim session.

        :param timeout: int - maximum time in seconds to wait for emssim session to start (default=180).
        :param bts_id (enb_id): int - EMSsim instance number to be started.
        :param alias: User defined alias used in setup_emss
        :param host: EMSsim server IP address (default: taken from ta_emss library constructor)
        :param port: EMSsim session TCP port (default: 4000 + bts_id)
        :param start_params: a set of parameters passed to emssim session start script.

        +----------------+-------------------+
        |  Examples                          |
        +================+===================+
        |  start_emss    | bts_id=2          |
        +----------------+-------------------+
        """
        timeout = self._opt_int(timeout)
        bts_id = self._opt_id(enb_id, bts_id)
        port = self._opt_int(port)

        self = self._get_instance(bts_id, alias, host=host, port=port, check_emss=False)

        self._timeout = timeout
        self.start_params = start_params
        self._start_emss()

    def stop_emss(self, enb_id=None, bts_id=None, alias=None, force=False):
        """
        Stops EMSsim session.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param force: Kill emssim session even if run_apps is False

        +----------------+-------------------+
        |  Examples                          |
        +================+===================+
        |  stop_emss     | bts_id=2          |
        +----------------+-------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias, check_emss=False)

        self._stop_emss(force=force)

    def logging_start(self, enb_id=None, bts_id=None, alias=None):
        """
        Starts logging of fbox events and EMSsim session.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +----------------+-------------------+
        |  Examples                          |
        +================+===================+
        |  logging_start | bts_id=1          |
        +----------------+-------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._log_om_start()

    def logging_stop(self, enb_id=None, bts_id=None, alias=None, pack=True, output_dir=None):
        """
        Stops logging of fbox events and EMSsim session.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param pack: pack and copy emssim logs to the current logging directory (default=True).
        :param output_dir: Output directory to store packed emssim logs (default=robot BuiltIn OUTPUT_DIR)

        +----------------+-------------------+
        |  Examples                          |
        +================+===================+
        |  logging_stop  | bts_id=1          |
        +----------------+-------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)
        pack = self._opt_bool(pack)

        self = self._get_instance(bts_id, alias)

        self._log_om_stop(pack, output_dir)

    def _print_info(self):
        print("Setting up EMSsim connection with following parameters:")
        print("Name..................: %s" % (str(self.emss_name)))
        print("Host..................: %s" % (str(self.emss_host)))
        print("Port..................: %s" % (str(self.emss_port)))
        print("User..................: %s" % (str(self.user)))
        print("Instance..............: %s" % (str(self._which_emss)))
        print("Alias.................: %s" % (str(self.alias)))
        print("EMSsim Connect Timeout: %s" % (str(self._timeout)))
        print("BTS Connect Timeout...: %s" % (str(self._bts_timeout)))
        print("Wait TCP Connected....: %s" % (str(self._desired_tcp_connected)))
        print("Wait OAM Connected....: %s" % (str(self._desired_connected)))
        print("Wait BTS Discovered...: %s" % (str(self._desired_discovered)))

    def _set_desired_states(self):
        if self._desired_tcp_connected:
            self._desired_connected = False
            self._desired_discovered = False

        if not self._desired_connected:
            self._desired_discovered = False

        if self._desired_discovered:
            self._desired_connected = True

    def _start_fbox_dual(self, fbox_dual_dir='/opt/emssim/proxy'):
        if self._is_fbox_running():
            return

        self._debug("Starting fbox_dual.pl")
        curr_dir = os.getcwd()
        try:
            os.chdir(fbox_dual_dir)
            start_fbox_process = pexpect.spawn("sudo perl fbox_dual.pl")
            match_index = start_fbox_process.expect([r"FBOX \[v\d+.\d+\] STARTED"], timeout=60)
            self._rep_exp("start_fbox_dual", match_index, start_fbox_process)
            if match_index == 0:
                self._debug("fbox_dual.pl started (%s)." % start_fbox_process.pid)
                time.sleep(5)
            start_fbox_process.close()
        except pexpect.EOF:
            self._debug("fbox_dual.pl spawned.")
        except pexpect.TIMEOUT:
            self._debug("Timeout waiting for fbox_dual.pl.")
        except Exception as exc:
            self._debug("Problem while running fbox_dual.pl: %s" % str(exc))
        finally:
            os.chdir(curr_dir)

        if self._is_fbox_running():
            self._debug("fbox_dual started. ")
        else:
            self._debug("fbox_dual not started. ")

    def _start_apache(self):
        out, err, rc = execute_shell_command("systemctl status apache2")
        if rc == 0:
            self._debug("Apache2 server already running")
            return

        out, err, rc = execute_shell_command("sudo systemctl start apache2")
        if rc == 0:
            self._debug("Apache2 server started successfully")
        else:
            self._debug(f"Cannot start apache2 server (rc={rc}): {err}")

    def _start_emss(self):
        if self._is_emss_running():
            return

        self._upgrade_emss()
        self._start_log()

        self._debug("Starting emss")
        user_process = self._move_to_user()

        if user_process is None:
            return

        screen_logfile = os.environ['SCREEN_LOGFILE'] if 'SCREEN_LOGFILE' in os.environ else None
        if screen_logfile:
            start_cmd = ("mkdir ~/.screen; chmod 700 ~/.screen; SCREENDIR=$HOME/.screen screen -m -d -L -Logfile {} -S startemss ./start".format(screen_logfile))
        else:
            start_cmd = "mkdir ~/.screen; chmod 700 ~/.screen; SCREENDIR=$HOME/.screen screen -m -d -S startemss ./start"
        for (param, val) in self.start_params.items():
            if isinstance(val, six.string_types) or isinstance(val, six.integer_types):
                start_cmd += " -" + param.upper() + " " + str(val)

        self._execute_command("sudo rm -rf /var/run/screen/S-%s" % self.user)
        self._execute_command("sudo rm -rf /home/%s/.screen/*" % self.user)
        self._debug("Starting EMSsim with command: %s" % start_cmd)
        user_process.sendline(start_cmd)
        match_index = user_process.expect(
            [
                "%s.+$" % self.user,
                pexpect.TIMEOUT
            ],
            timeout=30)
        self._rep_exp("start_emss", match_index, user_process)
        self._flush_exp(user_process)
        try:
            user_process.close()
        except Exception as exc:
            self._debug("Cannot terminate user login process: %s" % str(exc))
        self._debug("Waiting for EMSsim %s session to get eNB IP from fbox" % str(self.user))
        self._wait_for_emss_socket(timeout=60)
        self._check_if_emss_started()

    def _stop_emss(self, check_if_host_local=False, force=False):
        if self.is_logging:
            self._log_om_stop()

        if check_if_host_local:
            if self._is_host_local():
                self._kill_emss(force=force)
        else:
            self._kill_emss(force=force)

        try:
            devicemanager.remove_device_from_registry(self.emss_name)
            self.emssim = None
            self.om = None
            self.run_setup = True
        except Exception as exc:
            self._debug("Cannot deregister emssim: %s" % str(exc))

    def _create_emssim(self):
        try:
            self.emssim = devicemanager.get_device(name=self.emss_name, device_class=EMSsim,
                                                   port=self.emss_port, host=self.emss_host, logging=self.logging)
        except Exception as exc:
            self.emssim = None
            self._print("Cannot create emssim in device manager: %s" % str(exc))

    def _create_om(self):
        try:
            from ta_emss.utilities.oam.om import OM
            self.om = OM(enb_name=str(self.instance_id), logger=None, ute_emss=self)
        except Exception as exc:
            self._print("Cannot create om component: %s" % str(exc))
            return False
        return True

    def _is_fbox_running(self):
        if self._get_fbox_dual_pid():
            return True
        else:
            return False

    def _is_emss_running(self):
        if self._get_emss_start_pids():
            return True
        else:
            return False

    def _check_if_emss_started(self):
        if len(self._get_emss_start_pids()) >= 2:
            connected = False
            self._print("EMSsim started. Checking connection...")
            start_time = time.time()
            try:
                interval = 2
                while interval < self._timeout:
                    time.sleep(interval)
                    if self._check_emss_connection():
                        self._print("EMSsim connected after %s [s]" % str(int(time.time() - start_time)))
                        connected = True
                        break
                    self._debug("EMSsim not connected yet (%s)" % str(interval))
                    interval *= 2
            except Exception as exc:
                self._print("Cannot verify connection to EMSsim: %s" % str(exc))

            if not connected:
                raise ErrTransportTimeout("Cannot connect to EMSsim JSON RPC on %s:%s" % (self.emss_host, str(self.emss_port)))
        else:
            self._print("EMSsim not started.")

    def _check_emss_connection(self, silent=False):
        emss_sock = None
        try:
            emss_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        except socket.error as serr:
            self._print("FATAL: Cannot create emssim socket: %s" % str(serr))
            return False

        try:
            emss_sock.connect((self.emss_host, self.emss_port))
            if not silent:
                self._print("Connected to emssim (%s, %s)" % (str(self.emss_host), str(self.emss_port)))
            emss_sock.close()
            time.sleep(1)
            return True
        except socket.error as serr:
            emss_sock.close()
            time.sleep(1)
            if not silent:
                self._print("Cannot connect to emssim socket (%s, %s): %s" % (str(self.emss_host), str(self.emss_port), str(serr)))
        return False

    def _cleanup_old_logs(self):
        emssim_log_dir = self.log_dir
        self._execute_command("sudo mkdir -p %s" % emssim_log_dir)
        self._execute_command("sudo chmod a+wx %s" % emssim_log_dir)
        self._execute_command("sudo find %s -type f -mtime +3 -delete" % emssim_log_dir)
        self._execute_command("sudo find %s -type f -mtime +1 -exec gzip '{}' \\;" % emssim_log_dir)

    def _log_om_start(self):
        if self.is_logging:
            return

        debug_fbox = 1
        try:
            if not self._debug_fbox:
                # User forced setup_emss with debug_fbox=False
                debug_fbox = 0
            if self.debug_om is not None and not self.debug_om:
                # User defined DEBUG_OM=0
                debug_fbox = 0
        except Exception:
            pass

        try:
            self.is_logging = True
            log_cmd = self.emssim.cmd_log()
            log_cmd.run(["on", debug_fbox])
            self._print("EMSsim logging enabled")
        except Exception as exc:
            self._print("EMSsim logging not enabled (%s)" % (str(exc)))

    def _log_om_stop(self, pack=True, output_dir=None):
        if not self.is_logging:
            return

        if output_dir is None:
            output_dir = self.robot_log_dir

        try:
            self.is_logging = False
            log_cmd = self.emssim.cmd_log()
            log_cmd.run("off")
            self._print("EMSsim logging disabled")
            if pack:
                self._pack_logs(output_dir)
        except Exception as exc:
            self._print("EMSsim logging not disabled (%s)" % (str(exc)))

    def _check_if_enb_connected_discovered(self):
        if self._desired_tcp_connected or self._desired_connected or self._desired_discovered:
            self._print("Waiting for: tcp_connected=%s, connected=%s, discovered=%s." %
                        (str(self._desired_tcp_connected), str(self._desired_connected), str(self._desired_discovered)))
        else:
            return

        set_oam_ip = True
        activate_ne3s = False
        if self.ne3s:
            set_oam_ip = False
            activate_ne3s = True

        if self._is_btsmed():
            set_oam_ip = True
            activate_ne3s = False

        self._wait_for_connection_conditions(set_oam_ip, activate_ne3s)

    def _get_wait_for_connection_interval(self):
        if self._is_btsmed():
            return 30
        return 360

    def _wait_for_connection_conditions(self, set_oam_ip, activate_ne3s):
        tcp_connected = 0
        oam_connected = 0
        discovered = 0

        wait_interval = self._get_wait_for_connection_interval()
        emss_waiting_time = 0
        bts_waiting_time = 0
        bts_cs = self.emssim.cmd_bts_connection_status()
        while True:
            self._print("*** BTS waiting time: {}, EMSS waiting time: {}".format(bts_waiting_time, emss_waiting_time))
            try:
                if bts_cs.run():
                    bts_cs_ret = bts_cs.returned_data()
                    tcp_connected = bts_cs_ret['tcp_connection_status']
                    oam_connected = bts_cs_ret['connection_status']
                    discovered = bts_cs_ret['discover_status']
                    if self._check_enb_connected_discovered_conditions(tcp_connected, oam_connected, discovered):
                        break

                    self._print("tcp_connection_status={}, connection_status={}, discover_status{}".format(tcp_connected, oam_connected, discovered))

                    if set_oam_ip:
                        set_oam_ip = False
                        self._soam_activate()

                    if activate_ne3s:
                        self._coam_activate()

                    bts_waiting_time += self._wait_for_discover(timeout=wait_interval)

                    if bts_waiting_time > self._bts_timeout:
                        self._print("Timeout waiting for BTS to connect/discover")
                        break
                else:
                    self._print("Cannot run bts_connection_status command")
                    if not self.emssim.is_running():
                        self._print("EMSsim is not running")
                        break
                    if emss_waiting_time >= self._timeout:
                        break
                    self._print("Sleeping for {} [s]".format(wait_interval))
                    time.sleep(wait_interval)
                    emss_waiting_time += wait_interval

                self._print("BTS tcp_connected=%s, oam_connected=%s, discovered=%s (bts=%s)(emss=%s)" %
                            (str(tcp_connected), str(oam_connected), str(discovered), str(bts_waiting_time), str(emss_waiting_time)))
            except Exception as exc:
                self._print("Cannot verify BTS discovery status: %s" % str(exc))
                if emss_waiting_time >= self._timeout:
                    break
                self._print("[EXC] Sleeping for {} [s]".format(wait_interval))
                time.sleep(wait_interval)
                emss_waiting_time += wait_interval

        self._check_assert_connection_states(tcp_connected, oam_connected, discovered)

    def _soam_activate(self):
        if not self.is_ute:
            return
        self._print("Setting OAM IP")
        self.run_emssim_command("soam_oam_ip", timeout=10 * 60)

    def _coam_activate(self):
        params = ""
        if self.reg_user:
            params += " -user " + self.reg_user
        if self.reg_password:
            params += " -password " + self.reg_password
        if self.tls:
            params += " -tls 1"
        if self.pnp:
            params += " -pnp"
        if self.ac:
            params += " -ac"
        if self.certm:
            params += " -certm"
        if self.manager_id:
            params += " -manager_id " + self.manager_id

        self._print("Activating NE3S with params=[%s]" % params)
        self.run_emssim_command("ne3s_activate", params)

    def _check_enb_connected_discovered_conditions(self, tcp_connected, oam_connected, discovered):
        if tcp_connected:
            if not self._time_tcp_connected:
                self._time_tcp_connected = time.time()
            if self._desired_tcp_connected:
                return True
        if discovered:
            if not self._time_enb_discovered:
                self._time_enb_discovered = time.time()
        if oam_connected and (discovered or not self._desired_discovered):
            return True
        return False

    def _wait_for_discover(self, timeout):
        start_time = time.time()
        if self._desired_discovered:
            self._print("Waiting for BTS discovery: {} [s]".format(timeout))
            self.emssim.subscribe_events(event_type='discover')
            wait_time = 0
            while wait_time < timeout:
                disc_events = self.emssim.get_events(event_type='discover')
                succeeded = [evt for evt in disc_events if evt == "SUCCESS"]
                if len(succeeded):
                    break
                else:
                    wait_time += 1
                    time.sleep(1)
            self.emssim.unsubscribe_events(event_type='discover')
        else:
            time.sleep(timeout)
        waiting_time = int(time.time() - start_time)
        return waiting_time

    def _check_assert_connection_states(self, tcp_connected, oam_connected, discovered):
        self._print("BTS tcp_connected=%s, oam_connected=%s, discovered=%s" %
                    (str(tcp_connected), str(oam_connected), str(discovered)))
        if self._desired_tcp_connected:
            self._assert(tcp_connected, "BTS has not connected")
        if self._desired_connected:
            self._assert(oam_connected, "BTS OAM has not connected")
        if self._desired_discovered:
            self._assert(discovered, "BTS has not discovered")

    def _get_fbox_dual_pid(self):
        ps_out = self._execute_command("ps -eo euser,pid,ppid,cmd")
        pids = []
        patt = r"^\s*(\S+)\s+(\d+)\s+(\d+)\s+(.*)"
        for line in ps_out:
            srch = re.search(patt, line)
            if srch:
                euser = srch.group(1)
                pid = srch.group(2)
                # ppid = srch.group(3)
                cmd = srch.group(4)
                if re.search(r"^[a-z\/]*perl\s+[\.\/]*fbox_dual\.pl", cmd):
                    self._debug("fbox_dual.pl started for %s with pid=%s." % (str(euser), str(pid)))
                    pids.append(pid)
                    self._debug("Requesting to reload config for fbox_dual.pl pid=%s." % str(pid))
                    self._execute_command("sudo kill -s 1 %s" % str(pid))
        self._debug("FBOX_DUAL pid: %s" % str(pids))
        return pids

    def _wait_for_emss_socket(self, timeout):
        period = 1
        self._print("Waiting for EMSsim socket: %s:%s" % (str(self.emss_host), str(self.emss_port)))
        while timeout > 0:
            timeout = timeout - period
            time.sleep(period)
            if self._check_emss_socket_ready():
                self._print("EMSsim socket is ready")
                return

    def _check_emss_socket_ready(self):
        patt = r"\s+" + str(self.emss_host) + ":" + str(self.emss_port) + r"\s+"
        ns_out = self._execute_command("netstat -nlt")
        for line in ns_out:
            srch = re.search(patt, line)
            if srch:
                return True
        return False

    def _get_emss_start_pids(self):
        ps_out = self._execute_command("ps -eo euser:16,pid,ppid,cmd")
        pids = []
        # patt = r"^\s*" + self.user + r"\s+(\d+)\s+(\d+)\s+(.*)"
        patt = r"^\s*\S+\s+(\d+)\s+(\d+)\s+(.*)"
        for line in ps_out:
            srch = re.search(patt, line)
            if srch:
                pid = srch.group(1)
                # ppid = srch.group(2)
                cmd = srch.group(3)
                if re.search(r"^\S+perl\s+", cmd) and re.search(r"-JSON_PORT\s+" + str(self.emss_port) + r"\s+", cmd):
                    pids.append(pid)
        self._print("EMSS start pids: %s" % str(pids))
        return pids

    def _verify_add_user(self, user, bts_ip, force=False):
        if user is None:
            return
        if bts_ip is None:
            return
        try:
            path_to_start = "/home/%s/start" % user
            if os.path.isfile(path_to_start) and not force:
                self._print("Emssim start exists [%s]" % path_to_start)
                return
            self._print("Adding BTS user %s with IP=%s" % (user, bts_ip))
            add_user_cmd = "/opt/emssim/util/add_user.pl -u %s -ip %s" % (str(user), str(bts_ip))
            self._execute_command("sudo %s" % add_user_cmd)
        except Exception as exc:
            self._debug("Problem with user verification: %s" % str(exc))

    def _get_default_bts_ip(self, instance_id):
        if self.bts_ip:
            return self.bts_ip
        bts_ip = None
        ip_last_octet = instance_id * 2
        if ip_last_octet < 255:
            bts_ip = "10.0.1.%s" % ip_last_octet
        return bts_ip

    def _get_user_password(self):
        ret = self.user
        try:
            path_to_pwd = "/home/%s/.pwd" % self.user
            if os.path.isfile(path_to_pwd):
                pwd = self._read_last_not_empty_line(path_to_pwd)
                if pwd:
                    ret = pwd
                    self._print("Using password from pwd file: [%s]" % pwd)
        except Exception as exc:
            self._debug("Using default password due to problem with getting user password: %s" % str(exc))
        return ret

    def _get_port_from_start_script(self, user):
        ret = None
        try:
            path_to_start = "/home/%s/start" % user
            if os.path.isfile(path_to_start):
                ret = self._read_not_commented_line(path_to_start, r'JSON_PORT\s+(\d+)')
                self._print("Using JSON port from start file: [%s]" % ret)
        except Exception as exc:
            self._debug("Cannot get JSON port from EMSsim start script: %s" % exc)
        return ret

    def _get_server_port_from_start_script(self, user):
        ret = None
        try:
            path_to_start = "/home/%s/start" % user
            if os.path.isfile(path_to_start):
                ret = self._read_not_commented_line(path_to_start, r'SERVER_PORT\s+(\d+)')
                self._print("Using USER port from start file: [%s]" % ret)
        except Exception as exc:
            self._debug("Cannot get USER port from EMSsim start script: %s" % exc)
        return ret

    def _read_last_not_empty_line(self, path_to_file):
        ret = None
        with open(path_to_file) as f:
            lines = f.readlines()
            for line in lines:
                srch = re.search(r'(\S+)', line)
                if srch:
                    ret = srch.group(1)
        return ret

    def _read_not_commented_line(self, path_to_file, pattern):
        ret = ''
        with open(path_to_file) as f:
            lines = f.readlines()
            for line in lines:
                srch = re.search(r'\s*#', line)
                if srch:
                    continue
                srch = re.search(pattern, line)
                if srch:
                    ret = srch.group(1)
        return ret

    def _move_to_user(self):
        self._verify_add_user(user=self.user, bts_ip=self._get_default_bts_ip(self._which_emss), force=False)
        password = self._get_user_password()
        login_process = pexpect.spawn("sudo login %s" % self.user, timeout=30)
        match_index = login_process.expect("Password:")
        self._rep_exp("move_to_user-Password", match_index, login_process)
        self._flush_exp(login_process)
        login_process.sendline(password)
        match_index = login_process.expect(
            [
                "Login incorrect",
                "%s.+$" % self.user,
                pexpect.TIMEOUT
            ],
            timeout=5)
        self._rep_exp("move_to_user", match_index, login_process)
        self._flush_exp(login_process)
        if match_index == 0:
            self._print("Login failed for user %s (with pwd=%s)." % (self.user, password))
            try:
                login_process.close()
            except Exception as exc:
                self._debug("Cannot terminate login process: %s" % str(exc))
            return self._move_to_user_via_sudo()

        if self._is_logged_in(login_process):
            self._print("Login as %s succeeded" % self.user)
            return login_process
        return None

    def _move_to_user_via_sudo(self):
        login_process = pexpect.spawn("sudo su - %s" % self.user, timeout=30)
        match_index = login_process.expect(
            [
                "Login incorrect",
                "%s.+$" % self.user,
                pexpect.TIMEOUT
            ],
            timeout=5)
        self._rep_exp("move_to_user_via_sudo", match_index, login_process)
        self._flush_exp(login_process)
        if match_index == 0:
            self._print("Login failed via sudo for user %s." % (self.user))
            try:
                login_process.close()
            except Exception as exc:
                self._debug("Cannot terminate login process: %s" % str(exc))
            return None
        if self._is_logged_in(login_process):
            self._print("Login via sudo as %s succeeded" % self.user)
            return login_process
        return None

    def _is_logged_in(self, process):
        process.sendline("whoami")
        match_index = process.expect(['.+%s' % self.user,
                                      pexpect.TIMEOUT],
                                     timeout=5)
        self._rep_exp("is_logged_in", match_index, process)
        self._flush_exp(process)
        if match_index == 0:
            return True
        return False

    def _kill_emss(self, force=False):
        if not self.run_apps:
            if force:
                self._print("Force to kill emssim even if run_apps is False.")
            else:
                return
        self._kill_emss_processes()
        self._wait_emss_socket_released()
        if self._check_emss_socket_ready():
            self._print("WARNING: Emssim socket still present in OS")

    def _kill_emss_processes(self):
        tries = 1
        while tries <= 6:
            pids = self._get_emss_start_pids()
            if pids:
                kill_cmd = "sudo kill -9 " + " ".join(pids)
                self._print("EMSsim pids exist (%d), killing: %s" % (tries, kill_cmd))
                self._execute_command(kill_cmd)
            else:
                self._print("EMSsim killed (%d)" % tries)
                break
            tries = tries + 1
            time.sleep(10)

    def _wait_emss_socket_released(self):
        tries = 1
        while tries <= 6:
            if self._check_emss_connection(silent=True):
                self._print("EMSsim socket still active (%d)" % tries)
            else:
                self._print("EMSsim socket released (%d)" % tries)
                break
            tries = tries + 1
            time.sleep(10)

    def _rep_exp(self, fun, match_index, process):
        if self.debug_om is None or self.debug_om < 2:
            return
        self._debug("===> %s: match_index=%s" % (str(fun), str(match_index)))
        self._debug("---> %s: before=\n[%s]" % (str(fun), str(process.before)))
        try:
            self._debug("---> %s:  match=\n[%s]" % (str(fun), str(process.match.groups())))
        except Exception:
            self._debug("---> %s:  match=\n[%s]" % (str(fun), str(process.match)))
        self._debug("---> %s:  after=\n[%s]" % (str(fun), str(process.after)))

    def _flush_exp(self, proc):
        buff = ''
        try:
            while not proc.expect(r".+", timeout=1):
                buff += str(proc.match.group(0))
        except pexpect.TIMEOUT:
            pass
        self._debug("flush_exp: buff=[%s]" % str(buff), level=2)

    def _pack_logs(self, output_dir):
        if not output_dir:
            self._print("Empty output_dir - EMSsim logs will not be packed")
            return

        if not self.host_local:
            self._print("Not a local host - EMSsim logs will not be packed")
            return

        if not self.is_ute:
            self._print("Not in UTE - EMSsim logs will not be packed")
            return

        self._print("Packing EMSsim logs to %s" % output_dir)
        self._execute_command("/opt/emssim/util/pack_logs.pl %s" % output_dir)

    def _upgrade_emss(self):
        if not self.is_ute:
            return

        self._debug("Checking EMSsim for upgrades")

        current_ver = self._get_current_emss_version()
        current_ver_int = self._ver_str2int(current_ver)
        self._print("Current EMSsim version=%s" % current_ver)

        if 'EMSSIM_PACKAGE' in os.environ:
            emssim_pkg = os.environ['EMSSIM_PACKAGE']
            self._debug("Installing user defined package: %s" % emssim_pkg)
            self._download_and_install_package(emssim_pkg)
            return

        latest_ver = self._get_latest_emss_version()
        latest_ver_int = self._ver_str2int(latest_ver)
        self._print("Latest EMSsim version=%s" % latest_ver)

        if latest_ver_int > current_ver_int:
            emssim_pkg = "emssim_{ver}_amd64.deb".format(ver=latest_ver)
            self._print("Installing package: %s" % emssim_pkg)
            self._download_and_install_package(emssim_pkg)

    def _download_and_install_package(self, emssim_pkg):
        emssim_pkg_file = "/tmp/" + emssim_pkg

        if os.path.isfile(emssim_pkg_file):
            self._print("File exsists: {f}. Upgrade completed or already in progress.".format(f=emssim_pkg_file))
            return

        self._download_package(emssim_pkg, emssim_pkg_file)
        self._install_package(emssim_pkg_file)

    def _download_package(self, emssim_pkg, emssim_pkg_file):
        curl_cmd = self._get_curl_command("debs/" + emssim_pkg, add_opts="-o " + emssim_pkg_file, max_time=900, use_query=False)
        self._print("Downloading: %s" % curl_cmd)
        lines = self._run(curl_cmd, timeout=905)
        self._debug("Download status:")
        self._debug("-" * 80)
        for ln in lines:
            self._debug(ln)
        self._debug("-" * 80)

    def _run(self, cmd, timeout=180):
        out = [""]
        try:
            self._debug("Running: %s" % cmd)
            child = pexpect.spawn(cmd)
            child.expect(pexpect.EOF, timeout=timeout)
            out = child.before.decode('utf-8', 'ignore').split("\n")
            child.close()
            self._debug("Finished: %s" % cmd)
        except pexpect.TIMEOUT:
            self._debug("Timeout while running: %s" % cmd)
        except Exception as exc:
            self._debug("Error while running %s: %s" % (cmd, exc))
        return out

    def _run_cmd(self, cmd):
        out = ""
        retcode = None
        try:
            self._debug("Running command: %s" % cmd)
            out, err, retcode = execute_shell_command(cmd)
            if err:
                self._debug('Run command error: {}'.format(err))
        except Exception as exc:
            self._debug('Run command failed: {}'.format(exc))
        ret = out.split('\n')
        return ret, retcode

    def _execute_command(self, cmd):
        out = ""
        try:
            self._debug("Executing command: %s" % str(cmd))
            out, err, rc = execute_shell_command(cmd)
            if err:
                self._debug('Execute command error: {}'.format(err))
        except Exception as exc:
            self._debug("Command failed: %s" % str(exc))
        return out.split("\n")

    def _is_package_installed(self, package_name):
        dpkg_out = self._execute_command(f"dpkg -l {package_name}")
        for line in dpkg_out:
            if re.search(rf"^ii\s+{re.escape(package_name)}\s+", line):
                return True
        return False

    def _install_package(self, emssim_pkg_file):
        if os.path.isfile(emssim_pkg_file):
            try:
                self._print("Installing: %s" % emssim_pkg_file)
                dpkg_process = pexpect.spawn("sudo dpkg -i %s" % emssim_pkg_file)
                self._debug("<<PID>> dpkg: %s" % dpkg_process.pid)
                match_index = dpkg_process.expect(["FBOX log file is"], timeout=180)
                self._rep_exp("dpkg", match_index, dpkg_process)
                if match_index == 0:
                    self._print("Installed dpkg: %s" % emssim_pkg_file)
                    time.sleep(5)
                    self._execute_command("sudo kill -9 %s" % dpkg_process.pid)
                dpkg_process.close()
            except pexpect.EOF:
                self._print("Completed dpkg: %s" % emssim_pkg_file)
            except pexpect.TIMEOUT:
                self._print("Timeout running dpkg: %s" % emssim_pkg_file)
            except Exception as exc:
                self._print("Error while running dpkg: %s" % str(exc))
        else:
            self._print("Cannot install: %s. No such file." % emssim_pkg_file)

    def _ver_str2int(self, ver_str):
        srch = re.search(r"^\s*(\d+)\.(\d+)\.(\d+)\s*$", ver_str)
        if srch:
            return 1000000 * int(srch.group(1)) + 1000 * int(srch.group(2)) + int(srch.group(3))
        return 0

    def _get_current_emss_version(self):
        dpkg_out = self._execute_command("dpkg -l emssim")
        for line in dpkg_out:
            srch = re.search(r"emssim\s+(\d+\.\d+\.\d+)\s+", line)
            if srch:
                return srch.group(1)
        return "0.0.0"

    def _get_latest_emss_version(self):
        curl_out = self._run(self._get_curl_command("latest_ute_emssim.txt", connect_timeout=10, max_time=15), timeout=20)
        for line in curl_out:
            srch = re.search(r"^\s*(\d+\.\d+\.\d+)\s*$", line)
            if srch:
                return srch.group(1)
        return "0.0.0"

    def _get_curl_command(self, link, connect_timeout=60, max_time=900, add_opts=None, use_query=True):
        curl_cmd = "curl"
        if add_opts:
            curl_cmd += " {ao}".format(ao=add_opts)
        curl_cmd += " --connect-timeout {ct} --max-time {mt} -H 'Cache-Control: no-cache'".format(ct=connect_timeout, mt=max_time)
        curl_cmd += " {server}/{lk}".format(server=UTE_SERVER, lk=link)
        if use_query:
            curl_cmd += "?{q}".format(q="A" + str(int(time.time())))
        return curl_cmd

    def _is_host_local(self):
        emss_host = self.emss_host
        self._debug("*** Detecting localhost for EMSS_HOST=%s" % str(emss_host))
        ip_out = self._execute_command("ip addr show")
        for line in ip_out:
            srch = re.search(r"\s+inet\s+([0-9.]+)", line)
            if srch:
                ip = srch.group(1)
                self._debug("*** inet IP=%s" % ip)
                if ip == emss_host:
                    self._print("*** EMSsim local host detected")
                    return True
        self._print("*** EMSsim local host NOT detected")
        self.host_local = False
        return False

    def _add_secondary_oam_ip(self, sec_oam_ip):
        sec_oam_mask = '24'
        srch = re.search(r'(\S+)\/(\S+)', sec_oam_ip)
        if srch:
            sec_oam_ip = srch.group(1)
            sec_oam_mask = srch.group(2)
        pri_oam_ip = self._get_primary_oam_ip_from_emssim_config()
        if pri_oam_ip is None:
            self._print("WARNING: Cannot get Primary OAM IP from emssim.conf")
            return
        self._debug("*** Adding Secondary OAM IP=%s to the existing Primary OAM IP=%s" % (sec_oam_ip, pri_oam_ip))
        pri_if = self._get_if_for_ip(pri_oam_ip)
        self._print("IF for Primary OAM IP is: %s" % pri_if)
        if pri_if:
            self._execute_command("sudo ip addr add {}/{} dev {}".format(sec_oam_ip, sec_oam_mask, pri_if))

    def _get_if_for_ip(self, ip_arg):
        ips = self._get_if_addrs()
        self._print("IPs: %s" % ips)
        for eth in ips:
            for ip in ips[eth]:
                if ip == ip_arg:
                    return eth
        self._debug("Existing IPs: %s" % ips)
        return None

    def _get_if_addrs(self):
        ip_out = self._execute_command("ip addr show")
        ret = {}
        curr_eth = None
        for line in ip_out:
            srch = re.search(r"^\d+:\s*([^:]+):", line)
            if srch:
                curr_eth = srch.group(1)
                if curr_eth not in ret:
                    ret[curr_eth] = []
            srch = re.search(r"\s+inet\s+([0-9.]+)", line)
            if srch:
                ip = srch.group(1)
                ret[curr_eth].append(ip)
        return ret

    def _report_durations(self):
        if self._time_setup_start:
            if self._time_tcp_connected:
                self._print("TCP CONNECTED DURATION: %d [s]" % (self._time_tcp_connected - self._time_setup_start))
            if self._time_enb_discovered:
                self._print("ENB DISCOVERY DURATION: %d [s]" % (self._time_enb_discovered - self._time_setup_start))
            self._print("SETUP EMSS DURATION: %d [s]" % (time.time() - self._time_setup_start))

    def _debug(self, msg, level=0):
        if self.debug_om and self.debug_om > level:
            self._print(msg)

    def _print(self, msg):
        self._log("[EMSS STARTER][%s]: %s" % (self.user, str(msg)))
